{
  "title": "The Glass Diver's Escape",
  "gate_token": "QyqnrAt5VtFrqRRp420gVg",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The ruined city looms at dusk.",
      "visual_description": "Crumbling stone walls and collapsed towers under a smoky orange sky, tattered royal banners flutter from broken spires.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "Mara studies a faded map by the gate.",
      "visual_description": "Mara kneels before the massive iron castle gate, unrolling a parchment map while the gate's rusted hinges groan.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp warns of a cursed tower.",
      "visual_description": "The lamp's flame-eye flickers as it speaks, casting long shadows on the gate; a twisted spire rises behind it.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver slips through a shattered window.",
      "visual_description": "A clear diving helmet reflects the broken city lights as the rescuer passes through a jagged window frame into a dark hall.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "Inside, armored patrols march in silence.",
      "visual_description": "Empty suits of armor clank down a torchlit corridor, their visors dark, footsteps echoing on stone.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Tin Fox scouts ahead through rubble.",
      "visual_description": "The small clockwork fox picks its way over fallen stones, blue glass eyes glowing, tail winding as it moves.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "They find the Sleeping Tax Collector dozing.",
      "visual_description": "The tax collector slumps against a desk, head on a ledger book, stamped papers stuck to his sleeves like feathers.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Mara shakes him awake for information.",
      "visual_description": "Mara grabs the collector's shoulder; he stirs, blinking, while stamped papers flutter to the floor.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "He mumbles about a magic door in the east wing.",
      "visual_description": "The collector points a drowsy finger down a dark hallway, papers rustling, tin fox sniffing the air.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Glass Diver navigates a hall of mirrors.",
      "visual_description": "Reflections multiply in endless panes; the diver's helmet glints as they step carefully, avoiding phantom doubles.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The magic door glows with runes.",
      "visual_description": "A stone door etched with blue runes pulses softly, set in an archway covered in climbing ivy.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "Oracle Lamp deciphers the door's riddle.",
      "visual_description": "The lamp's flame eye scans the runes, casting shifting light patterns across the stone.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "Glass Diver opens the door with a mirror shard.",
      "visual_description": "The diver holds a reflective shard to the runes, which align and click; the door swings open silently.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "Beyond lies a treasury filled with illusions.",
      "visual_description": "Coins and gems glitter in piles, but coins dissolve into dust when touched; the room hums with false promises.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Tin Fox detects a hidden passage.",
      "visual_description": "The small fox sniffs at a tapestry, then pushes against a false wall that slides aside, revealing a dark tunnel.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "The rescue team regroups at the tunnel exit.",
      "visual_description": "All five characters gather at the tunnel mouth, overlooking a bridge that spans a deep chasm.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the bridge as it crumbles.",
      "visual_description": "Stones fall into the abyss; the team runs, the lamp swinging, the fox's claws scraping stone, the collector stumbling with papers flying.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They escape into the misty forest beyond.",
      "visual_description": "The ruined city fades behind them as they enter a silver fog among ancient trees, safe but weary.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

